using UnityEngine;using UnityEngine.UI;
public sealed partial class TrainingOverlay {
 public TrainingSession Session{get;private set;}public bool OptionTrainingVisible{get;private set;}public bool HudDamageVisible{get;private set;}=true;public bool HudCommandsVisible{get;private set;}=true;
 readonly TrainingCommandHistory commandsFirst=new TrainingCommandHistory(),commandsSecond=new TrainingCommandHistory();
 GameObject trainingOptions;RectTransform trainingContent;readonly System.Collections.Generic.List<TrainingOptionValue> trainingValues=new System.Collections.Generic.List<TrainingOptionValue>();readonly System.Collections.Generic.List<Button> jgButtons=new System.Collections.Generic.List<Button>();
 public void EnsureTrainingSession(){if(Session!=null)return;Session=GetComponent<TrainingSession>();if(Session==null)Session=gameObject.AddComponent<TrainingSession>();Session.Configure(this);}
 public void CaptureCommandDisplays(){commandsFirst.Capture(player);commandsSecond.Capture(player.opponent);}
 public void SetHudCommandsVisible(bool value){HudCommandsVisible=value;hudDirty=true;}
 public void SetHudDamageVisible(bool value){HudDamageVisible=value;hudDirty=true;}
 void CreateTrainingOptions(){EnsureTrainingSession();OptionButton("NavTraining","Training settings",optionPanel,()=>ShowTrainingOptions(true));trainingOptions=OptionObject("TrainingSettings",optionPanel);var scroll=trainingOptions.AddComponent<ScrollRect>();scroll.horizontal=false;scroll.vertical=true;scroll.movementType=ScrollRect.MovementType.Clamped;scroll.scrollSensitivity=24;var vp=OptionObject("Viewport",trainingOptions.transform);vp.AddComponent<Image>().color=new Color(0,0,0,.01f);vp.AddComponent<RectMask2D>();var v=(RectTransform)vp.transform;v.anchorMin=Vector2.zero;v.anchorMax=Vector2.one;v.offsetMin=v.offsetMax=Vector2.zero;scroll.viewport=v;trainingContent=(RectTransform)OptionObject("Content",v).transform;scroll.content=trainingContent;
  OptionText("Header","TRAINING | settings apply to this Play session",trainingContent,16);OptionText("PositionLabel","Reset position",trainingContent);for(int i=0;i<3;i++){int n=i;OptionButton("Position"+i,new[]{"Left","Center","Right"}[i],trainingContent,()=>Session.startPosition=(TrainingSession.StartPosition)n);}
  OptionButton("DisplayFrames","",trainingContent,()=>SetHudFramesVisible(!HudFramesVisible));OptionButton("DisplayDamage","",trainingContent,()=>SetHudDamageVisible(!HudDamageVisible));OptionButton("DisplayCommands","",trainingContent,()=>SetHudCommandsVisible(!HudCommandsVisible));
  for(int i=0;i<2;i++){int n=i;OptionText("PlayerHeader"+i,(i+1)+"P",trainingContent,16);Value("HP"+i,(i+1)+"P HP",1,100,()=>Session.Settings(n).hpPercent,x=>Session.SetHP(n,x));OptionButton("Recover"+i,"",trainingContent,()=>Session.Settings(n).recover=!Session.Settings(n).recover);Value("TG"+i,(i+1)+"P TG",-200,200,()=>Session.Settings(n).tg,x=>Session.SetTG(n,x));OptionButton("Fixed"+i,"",trainingContent,()=>Session.SetFixed(n,!Session.Settings(n).fixedTG));}
  OptionText("RecordInfo","R: 3-second countdown → control dummy; R again stops. Max 10s.\nP: one-shot playback. Ctrl: reset configured HP/TG/positions.\nOpening menu stops playback; saves a nonempty partial recording.\nRelease held controls at routing boundaries before operating the new actor.\nHP: J edit, W/S ±10, A/D ±1, J commit, K discard.\nHP recovery waits 3 simulation seconds after last HP damage and all stun/stop ends.\nTG fixed blocks every gameplay gain/spend; Ctrl applies the configured value.\nExisting v0.1 TG earning remains deferred even with fixed OFF.",trainingContent,13);
  OptionText("JGLabel","JG reduction (not input age)",optionPanel,13);for(int i=0;i<=10;i++){int n=i;jgButtons.Add(OptionButton("JG"+i,"-"+i+"F",optionPanel,()=>Session.dummyJG=n));}
  for(int i=0;i<guardButtons.Count;i++){int n=i;guardButtons[i].interactable=true;guardButtons[i].onClick.RemoveAllListeners();guardButtons[i].GetComponentInChildren<Text>().text=new[]{"None","Guard","FD","Always FD"}[i];guardButtons[i].onClick.AddListener(()=>Session.guardMode=(TrainingSession.DummyGuard)n);}
  optionPanel.Find("Note").GetComponent<Text>().text="FD: during opponent attack. Always FD: maintained while idle too. JG buttons set guard-stun reduction directly (0..10F), only for the automated dummy. Player JG is unchanged.";
  ShowTrainingOptions(true);
 }
 void Value(string id,string label,int min,int max,System.Func<int> get,System.Action<int> set){var button=OptionButton(id,"",trainingContent,null);var value=button.gameObject.AddComponent<TrainingOptionValue>();value.Configure(label,min,max,get,set);trainingValues.Add(value);}
 public void ShowTrainingOptions(bool visible){OptionTrainingVisible=visible;if(trainingOptions==null)return;if(!visible){trainingOptions.SetActive(false);return;}ShowInputOptions(false);OptionTrainingVisible=true;foreach(Transform child in optionPanel){if(child.name=="Title"||child.name=="Close"||child.name=="Pause"||(child.name.StartsWith("Nav")&&child.name!="Navigation")||child.name=="TrainingSettings"||child.name=="InputSettings"||child.name=="LocomotionSettings"||child.name=="ComparisonSettings")continue;child.gameObject.SetActive(false);}trainingOptions.SetActive(true);}
 void LayoutTrainingOptions(float w,float h,float left,float x,float right){if(trainingOptions==null)return;string[] nav={"NavTraining","NavDummy","NavInputs","NavLocomotion","NavComparison"};for(int i=0;i<nav.Length;i++){var t=optionPanel.Find(nav[i]);if(t!=null)OptionPlace((RectTransform)t,18,62+i*39,left-24,32);}OptionPlace((RectTransform)trainingOptions.transform,x,62,right,h-104);float scrollY=trainingContent.anchoredPosition.y;OptionPlace(trainingContent,0,0,right-8,600);trainingContent.anchoredPosition=new Vector2(0,Mathf.Clamp(scrollY,0,Mathf.Max(0,600-(h-104))));foreach(Transform child in trainingContent){string id=child.name;var r=(RectTransform)child;if(id=="Header")OptionPlace(r,0,0,right-8,28);else if(id=="PositionLabel")OptionPlace(r,0,36,120,30);else if(id.StartsWith("Position")){int n=int.Parse(id.Substring(8));OptionPlace(r,124+n*(right-132)/3,36,(right-140)/3,30);}else if(id.StartsWith("Display")){int n=id=="DisplayFrames"?0:id=="DisplayDamage"?1:2;OptionPlace(r,n*(right-8)/3,78,(right-16)/3,32);}else if(id.StartsWith("PlayerHeader")){int n=int.Parse(id.Substring(12));OptionPlace(r,0,126+n*118,right,24);}else if(id=="RecordInfo")OptionPlace(r,0,378,right-12,210);else{int n=id[id.Length-1]-'0';bool tg=id.StartsWith("TG")||id.StartsWith("Fixed");bool toggle=id.StartsWith("Fixed")||id.StartsWith("Recover");OptionPlace(r,toggle?right*.62f:0,154+n*118+(tg?42:0),toggle?right*.38f-10:right*.62f-8,34);}}
  if(!OptionTrainingVisible&&!OptionInputSettingsVisible&&!OptionLocomotionVisible&&!OptionComparisonVisible){OptionPlace((RectTransform)optionPanel.Find("JGLabel"),x,246,right,20);for(int i=0;i<jgButtons.Count;i++)OptionPlace((RectTransform)jgButtons[i].transform,x+i*right/11,270,right/11-3,29);OptionPlace((RectTransform)optionPanel.Find("CounterLabel"),x,310,right,25);OptionPlace((RectTransform)counterField.transform,x,339,right,34);OptionPlace(optionError.rectTransform,x,379,right,34);OptionPlace((RectTransform)optionPanel.Find("Note"),x,419,right,54);}
  RefreshTrainingOptions();
 }
 void RefreshTrainingOptions(){if(Session==null||trainingOptions==null)return;foreach(var value in trainingValues)if(value!=null)value.Refresh();SetLabel("DisplayFrames","Frames: "+(HudFramesVisible?"ON":"OFF"));SetLabel("DisplayDamage","Damage: "+(HudDamageVisible?"ON":"OFF"));SetLabel("DisplayCommands","Commands: "+(HudCommandsVisible?"ON":"OFF"));for(int i=0;i<2;i++){SetLabel("Recover"+i,"Recovery: "+(Session.Settings(i).recover?"ON":"OFF"));SetLabel("Fixed"+i,"TG fixed: "+(Session.Settings(i).fixedTG?"ON":"OFF"));}for(int i=0;i<3;i++)trainingContent.Find("Position"+i).GetComponent<Image>().color=(int)Session.startPosition==i?new Color(.25f,.48f,.36f):new Color(.14f,.22f,.20f);for(int i=0;i<jgButtons.Count;i++)jgButtons[i].GetComponent<Image>().color=i==Session.dummyJG?new Color(.25f,.48f,.36f):new Color(.14f,.22f,.20f);for(int i=0;i<guardButtons.Count;i++)guardButtons[i].GetComponent<Image>().color=i==(int)Session.guardMode?new Color(.25f,.48f,.36f):new Color(.14f,.22f,.20f);}
 void SetLabel(string id,string text){var t=trainingContent.Find(id);if(t!=null)t.GetComponentInChildren<Text>().text=text;}
}
